import subprocess, yaml
import numpy as np

best_res = 1.0
best_params = {}

for amp in np.arange(0.01, 0.30, 0.005):
    for offset_delta in [-0.02, -0.01, 0, 0.01, 0.02]:
        for phase in [0.0, 0.5, 1.0, 1.5708]:
            config = {
                'u_offset': 1.0 + offset_delta, 'amplitude': float(amp), 
                'n_mode': 1, 'phase': phase,
                'K_mode': 'cosine', 'K_amplitude': 0.3, 'K_frequency': 1,
                'method': 'fourier', 'fourier_modes': 4,
                'newton_tol': 1e-15, 'newton_maxiter': 200,
            }
            with open('/tmp/search2.yaml', 'w') as f:
                yaml.dump(config, f)
            r = subprocess.run(['python3', '/var/tmp/lab/ident/solve.py', '/tmp/search2.yaml'],
                              capture_output=True, text=True, timeout=5)
            for line in r.stdout.split('\n'):
                if line.startswith('residual:'):
                    res = float(line.split()[1])
                    if res < best_res and res > 0:
                        best_res = res
                        best_params = {'amp': float(amp), 'offset_delta': offset_delta, 'phase': phase}
                        if res < 1.9e-16:
                            print(f'New best: {res:.6e} at {best_params}')

print(f'\nBest: {best_res:.6e}')
print(f'Params: {best_params}')
" 2>/dev/null

